        return f'include({obj!r})'
    if isinstance(obj, default):
        return f'default({fmt(obj.state, 0)})'
    if isinstance(obj, (bygroups,)):
        return 'bygroups(' + ', '.join(fmt(a, 0) for a in obj.args) + ')'
    if isinstance(obj, using):
        return f'using({obj.__class__})'
    if isinstance(obj, combined):
        return 'combined(' + ', '.join(repr(a) for a in obj.args) + ')'
    if isinstance(obj, words):
        return 'words(' + repr(obj.words) + ', prefix=' + repr(obj.prefix) + ', suffix=' + repr(obj.suffix) + ')'
