            s += ', ' + fmt(obj[2], 0)
        return s + ')'
    if isinstance(obj, (tuple, list)):
        return '(' + ', '.join(fmt(a, 0) for a in obj) + ')'
    return str(obj)  # tokens stringified

def dump(cls):
    print('=' * 20, cls.__name__)
    for state, rules in cls.tokens.items():
        print(f'--- state {state!r}:')
        if isinstance(rules, str):
            print('   ', rules); continue
        for r in rules:
            print('   ', fmt(r, 0))

