import sys, types
sys.path.insert(0, '/tmp/hl2/pyx')
from pygments.lexer import include, default, words, combined, _inherit

def fmt(obj):
    if obj is None:
        return 'None'
    if obj is _inherit:
        return 'inherit'
    if isinstance(obj, str):
        return repr(obj)
    if isinstance(obj, include):
        return f'include({obj!r})'
    if isinstance(obj, default):
        return f'default({fmt(obj.state)})'
    if isinstance(obj, words):
        return f'words({list(obj.words)!r}, prefix={obj.prefix!r}, suffix={obj.suffix!r})'
    if isinstance(obj, combined):
        return 'combined(' + ', '.join(repr(a) for a in obj.args) + ')'
    if isinstance(obj, types.FunctionType):
        fv = obj.__code__.co_freevars
        cells = [c.cell_contents for c in (obj.__closure__ or [])]
        env = dict(zip(fv, cells))
        if 'args' in env:  # bygroups
            return 'bygroups(' + ', '.join(fmt(a) for a in env['args']) + ')'
        if 'cls' in env:  # using
            return 'using(' + env['cls'].__name__ + ')'
        return '<func ' + obj.__code__.co_name + '>'
    if isinstance(obj, tuple):
        return '(' + ', '.join(fmt(a) for a in obj) + ')'
    if isinstance(obj, list):
        return '[' + ', '.join(fmt(a) for a in obj) + ']'
    s = str(obj)
    if s.startswith('Token.'):
        return s[6:]
    return s

def dump(cls):
    print('=' * 20, cls.__name__)
    for state, rules in cls.tokens.items():
        print(f'--- state {state!r}:')
        if isinstance(rules, str):
            print('   ', rules); continue
        for r in rules:
            print('   ', fmt(r))

import pygments.lexers as L
for name in sys.argv[1:]:
    dump(getattr(L, name))

